<?php
namespace App\Http\Controllers;
use App\Models\Order; use App\Models\Transaction; use App\Models\WebhookEvent; use App\Services\OrderStateService; use App\Services\PaystackService; use Illuminate\Http\Request;
class PaymentController extends Controller {
 public function callback(Request $r,PaystackService $paystack,OrderStateService $states){$reference=$r->string('reference')->toString();$data=$paystack->verify($reference);$order=Order::where('payment_reference',$reference)->firstOrFail();if(($data['status']??'')==='success'){$order->update(['payment_status'=>'SUCCESS']);Transaction::firstOrCreate(['provider_reference'=>$reference],['order_id'=>$order->id,'provider'=>'paystack','type'=>'PAYMENT','amount_kobo'=>$order->amount_kobo,'currency'=>'NGN','status'=>'SUCCESS']);if($order->status==='PENDING')$states->transition($order,'AUTHORIZED',auth()->id(),'Paystack payment verified.');return redirect()->route('orders.show',$order)->with('success','Payment verified.');}return redirect()->route('orders.show',$order)->withErrors(['payment'=>'Payment was not successful.']);}
 public function webhook(Request $r,PaystackService $paystack,OrderStateService $states){$payload=$r->getContent();$sig=$r->header('x-paystack-signature','');abort_unless($paystack->validWebhook($payload,$sig),401);$json=$r->json()->all();$eventId=$json['data']['reference']??sha1($payload);$event=WebhookEvent::firstOrCreate(['provider'=>'paystack','event_id'=>$eventId],['payload'=>$json]);if($event->processed_at)return response()->json(['ok'=>true]);if(($json['event']??'')==='charge.success'){$ref=$json['data']['reference']??null;if($ref && ($order=Order::where('payment_reference',$ref)->first())){$order->update(['payment_status'=>'SUCCESS']);if($order->status==='PENDING')$states->transition($order,'AUTHORIZED',null,'Paystack webhook verified.');}}$event->update(['processed_at'=>now()]);return response()->json(['ok'=>true]);}
}
